$tmp=Join-Path $env:TEMP 'pc-iphone-eval-e1.mjs'
try {
[System.IO.File]::WriteAllText($tmp,@'
const die=setTimeout(()=>{console.log(JSON.stringify({status:'hard_timeout'}));process.exit(0)},5500);
try{
 const a=await(await fetch('http://127.0.0.1:17447/json/list')).json();
 const t=a.find(x=>x.id==='5BE7D591DA96F1CAFD3416FF88E7DE17');
 if(!t)throw Error('tab_missing');
 const w=new WebSocket(t.webSocketDebuggerUrl);
 w.addEventListener('open',()=>w.send(JSON.stringify({id:1,method:'Runtime.evaluate',params:{expression:'({url:location.pathname,title:document.title,items:document.querySelectorAll(\'[data-marker=item]\').length})',returnByValue:true}})),{once:true});
 w.addEventListener('message',e=>{const z=JSON.parse(e.data);if(z.id===1){console.log(JSON.stringify({status:'reply',data:z.result?.result?.value,error:z.error?.message,ex:z.result?.exceptionDetails?.text}));process.exit(0)}},{once:false});
 w.addEventListener('error',e=>{console.log(JSON.stringify({status:'ws_error'}));process.exit(0)},{once:true});
}catch(e){console.log(JSON.stringify({status:'error',error:String(e).slice(0,160)}));process.exit(0)}
'@,[System.Text.UTF8Encoding]::new($false))
& node.exe $tmp
